/bin/bash -c "python3 - <<'PY'
from itertools import product
for pu,pv in [(1,2),(2,1)]:
 P={(0,i):int(pu==i) for i in (1,2)}|{(1,i):int(pv==i) for i in (1,2)}
 witness=None
 for zvals in product((0,1),repeat=4):
  Z=dict(zip(P,zvals))
  if all(Z[(v,i)]>=P[(v,i)] for v in (0,1) for i in (1,2)) and all(Z[(1,i)]<=Z[(0,i)] and Z[(1,i)]<=P[(1,i)]-P[(0,i)]+1 for i in (1,2)):
   witness=Z
   break
 comm=P[(0,1)]*P[(1,2)]
 print({'stage_u':pu,'stage_v':pv,'constraints_6_feasible':witness is not None,'Z_witness':str(witness),'eq4_communication_cost':comm,'eq2_TPI_with_unit_layer_cost_and_2_microbatches':2+comm+max(1,comm)})
PY"
